mkfn!{
    scope_introspect!();
    # [doc = " Creates a \"fork-join\" scope `s` and invokes the closure with a"] # [doc = " reference to `s`. This closure can then spawn asynchronous tasks"] # [doc = " into `s`. Those tasks may run asynchronously with respect to the"] # [doc = " closure; they may themselves spawn additional tasks into `s`. When"] # [doc = " the closure returns, it will block until all tasks that have been"] # [doc = " spawned into `s` complete."] # [doc = ""] # [doc = " `scope()` is a more flexible building block compared to `join()`,"] # [doc = " since a loop can be used to spawn any number of tasks without"] # [doc = " recursing. However, that flexibility comes at a performance price:"] # [doc = " tasks spawned using `scope()` must be allocated onto the heap,"] # [doc = " whereas `join()` can make exclusive use of the stack. **Prefer"] # [doc = " `join()` (or, even better, parallel iterators) where possible.**"] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " The Rayon `join()` function launches two closures and waits for them"] # [doc = " to stop. One could implement `join()` using a scope like so, although"] # [doc = " it would be less efficient than the real implementation:"] # [doc = ""] # [doc = " ```rust"] # [doc = " # use rustc_thread_pool as rayon;"] # [doc = " pub fn join<A,B,RA,RB>(oper_a: A, oper_b: B) -> (RA, RB)"] # [doc = "     where A: FnOnce() -> RA + Send,"] # [doc = "           B: FnOnce() -> RB + Send,"] # [doc = "           RA: Send,"] # [doc = "           RB: Send,"] # [doc = " {"] # [doc = "     let mut result_a: Option<RA> = None;"] # [doc = "     let mut result_b: Option<RB> = None;"] # [doc = "     rayon::scope(|s| {"] # [doc = "         s.spawn(|_| result_a = Some(oper_a()));"] # [doc = "         s.spawn(|_| result_b = Some(oper_b()));"] # [doc = "     });"] # [doc = "     (result_a.unwrap(), result_b.unwrap())"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " # A note on threading"] # [doc = ""] # [doc = " The closure given to `scope()` executes in the Rayon thread-pool,"] # [doc = " as do those given to `spawn()`. This means that you can't access"] # [doc = " thread-local variables (well, you can, but they may have"] # [doc = " unexpected values)."] # [doc = ""] # [doc = " # Task execution"] # [doc = ""] # [doc = " Task execution potentially starts as soon as `spawn()` is called."] # [doc = " The task will end sometime before `scope()` returns. Note that the"] # [doc = " *closure* given to scope may return much earlier. In general"] # [doc = " the lifetime of a scope created like `scope(body)` goes something like this:"] # [doc = ""] # [doc = " - Scope begins when `scope(body)` is called"] # [doc = " - Scope body `body()` is invoked"] # [doc = "     - Scope tasks may be spawned"] # [doc = " - Scope body returns"] # [doc = " - Scope tasks execute, possibly spawning more tasks"] # [doc = " - Once all tasks are done, scope ends and `scope()` returns"] # [doc = ""] # [doc = " To see how and when tasks are joined, consider this example:"] # [doc = ""] # [doc = " ```rust"] # [doc = " # use rustc_thread_pool as rayon;"] # [doc = " // point start"] # [doc = " rayon::scope(|s| {"] # [doc = "     s.spawn(|s| { // task s.1"] # [doc = "         s.spawn(|s| { // task s.1.1"] # [doc = "             rayon::scope(|t| {"] # [doc = "                 t.spawn(|_| ()); // task t.1"] # [doc = "                 t.spawn(|_| ()); // task t.2"] # [doc = "             });"] # [doc = "         });"] # [doc = "     });"] # [doc = "     s.spawn(|s| { // task s.2"] # [doc = "     });"] # [doc = "     // point mid"] # [doc = " });"] # [doc = " // point end"] # [doc = " ```"] # [doc = ""] # [doc = " The various tasks that are run will execute roughly like so:"] # [doc = ""] # [doc = " ```notrust"] # [doc = " | (start)"] # [doc = " |"] # [doc = " | (scope `s` created)"] # [doc = " +-----------------------------------------------+ (task s.2)"] # [doc = " +-------+ (task s.1)                            |"] # [doc = " |       |                                       |"] # [doc = " |       +---+ (task s.1.1)                      |"] # [doc = " |       |   |                                   |"] # [doc = " |       |   | (scope `t` created)               |"] # [doc = " |       |   +----------------+ (task t.2)       |"] # [doc = " |       |   +---+ (task t.1) |                  |"] # [doc = " | (mid) |   |   |            |                  |"] # [doc = " :       |   + <-+------------+ (scope `t` ends) |"] # [doc = " :       |   |                                   |"] # [doc = " |<------+---+-----------------------------------+ (scope `s` ends)"] # [doc = " |"] # [doc = " | (end)"] # [doc = " ```"] # [doc = ""] # [doc = " The point here is that everything spawned into scope `s` will"] # [doc = " terminate (at latest) at the same point -- right before the"] # [doc = " original call to `rayon::scope` returns. This includes new"] # [doc = " subtasks created by other subtasks (e.g., task `s.1.1`). If a new"] # [doc = " scope is created (such as `t`), the things spawned into that scope"] # [doc = " will be joined before that scope returns, which in turn occurs"] # [doc = " before the creating task (task `s.1.1` in this case) finishes."] # [doc = ""] # [doc = " There is no guaranteed order of execution for spawns in a scope,"] # [doc = " given that other threads may steal tasks at any time. However, they"] # [doc = " are generally prioritized in a LIFO order on the thread from which"] # [doc = " they were spawned. So in this example, absent any stealing, we can"] # [doc = " expect `s.2` to execute before `s.1`, and `t.2` before `t.1`. Other"] # [doc = " threads always steal from the other end of the deque, like FIFO"] # [doc = " order. The idea is that \"recent\" tasks are most likely to be fresh"] # [doc = " in the local CPU's cache, while other threads can steal older"] # [doc = " \"stale\" tasks. For an alternate approach, consider"] # [doc = " [`scope_fifo()`] instead."] # [doc = ""] # [doc = " [`scope_fifo()`]: fn.scope_fifo.html"] # [doc = ""] # [doc = " # Accessing stack data"] # [doc = ""] # [doc = " In general, spawned tasks may access stack data in place that"] # [doc = " outlives the scope itself. Other data must be fully owned by the"] # [doc = " spawned task."] # [doc = ""] # [doc = " ```rust"] # [doc = " # use rustc_thread_pool as rayon;"] # [doc = " let ok: Vec<i32> = vec![1, 2, 3];"] # [doc = " rayon::scope(|s| {"] # [doc = "     let bad: Vec<i32> = vec![4, 5, 6];"] # [doc = "     s.spawn(|_| {"] # [doc = "         // We can access `ok` because outlives the scope `s`."] # [doc = "         println!(\"ok: {:?}\", ok);"] # [doc = ""] # [doc = "         // If we just try to use `bad` here, the closure will borrow `bad`"] # [doc = "         // (because we are just printing it out, and that only requires a"] # [doc = "         // borrow), which will result in a compilation error. Read on"] # [doc = "         // for options."] # [doc = "         // println!(\"bad: {:?}\", bad);"] # [doc = "    });"] # [doc = " });"] # [doc = " ```"] # [doc = ""] # [doc = " As the comments example above suggest, to reference `bad` we must"] # [doc = " take ownership of it. One way to do this is to detach the closure"] # [doc = " from the surrounding stack frame, using the `move` keyword. This"] # [doc = " will cause it to take ownership of *all* the variables it touches,"] # [doc = " in this case including both `ok` *and* `bad`:"] # [doc = ""] # [doc = " ```rust"] # [doc = " # use rustc_thread_pool as rayon;"] # [doc = " let ok: Vec<i32> = vec![1, 2, 3];"] # [doc = " rayon::scope(|s| {"] # [doc = "     let bad: Vec<i32> = vec![4, 5, 6];"] # [doc = "     s.spawn(move |_| {"] # [doc = "         println!(\"ok: {:?}\", ok);"] # [doc = "         println!(\"bad: {:?}\", bad);"] # [doc = "     });"] # [doc = ""] # [doc = "     // That closure is fine, but now we can't use `ok` anywhere else,"] # [doc = "     // since it is owned by the previous task:"] # [doc = "     // s.spawn(|_| println!(\"ok: {:?}\", ok));"] # [doc = " });"] # [doc = " ```"] # [doc = ""] # [doc = " While this works, it could be a problem if we want to use `ok` elsewhere."] # [doc = " There are two choices. We can keep the closure as a `move` closure, but"] # [doc = " instead of referencing the variable `ok`, we create a shadowed variable that"] # [doc = " is a borrow of `ok` and capture *that*:"] # [doc = ""] # [doc = " ```rust"] # [doc = " # use rustc_thread_pool as rayon;"] # [doc = " let ok: Vec<i32> = vec![1, 2, 3];"] # [doc = " rayon::scope(|s| {"] # [doc = "     let bad: Vec<i32> = vec![4, 5, 6];"] # [doc = "     let ok: &Vec<i32> = &ok; // shadow the original `ok`"] # [doc = "     s.spawn(move |_| {"] # [doc = "         println!(\"ok: {:?}\", ok); // captures the shadowed version"] # [doc = "         println!(\"bad: {:?}\", bad);"] # [doc = "     });"] # [doc = ""] # [doc = "     // Now we too can use the shadowed `ok`, since `&Vec<i32>` references"] # [doc = "     // can be shared freely. Note that we need a `move` closure here though,"] # [doc = "     // because otherwise we'd be trying to borrow the shadowed `ok`,"] # [doc = "     // and that doesn't outlive `scope`."] # [doc = "     s.spawn(move |_| println!(\"ok: {:?}\", ok));"] # [doc = " });"] # [doc = " ```"] # [doc = ""] # [doc = " Another option is not to use the `move` keyword but instead to take ownership"] # [doc = " of individual variables:"] # [doc = ""] # [doc = " ```rust"] # [doc = " # use rustc_thread_pool as rayon;"] # [doc = " let ok: Vec<i32> = vec![1, 2, 3];"] # [doc = " rayon::scope(|s| {"] # [doc = "     let bad: Vec<i32> = vec![4, 5, 6];"] # [doc = "     s.spawn(|_| {"] # [doc = "         // Transfer ownership of `bad` into a local variable (also named `bad`)."] # [doc = "         // This will force the closure to take ownership of `bad` from the environment."] # [doc = "         let bad = bad;"] # [doc = "         println!(\"ok: {:?}\", ok); // `ok` is only borrowed."] # [doc = "         println!(\"bad: {:?}\", bad); // refers to our local variable, above."] # [doc = "     });"] # [doc = ""] # [doc = "     s.spawn(|_| println!(\"ok: {:?}\", ok)); // we too can borrow `ok`"] # [doc = " });"] # [doc = " ```"] # [doc = ""] # [doc = " # Panics"] # [doc = ""] # [doc = " If a panic occurs, either in the closure given to `scope()` or in"] # [doc = " any of the spawned jobs, that panic will be propagated and the"] # [doc = " call to `scope()` will panic. If multiple panics occurs, it is"] # [doc = " non-deterministic which of their panic values will propagate."] # [doc = " Regardless, once a task is spawned using `scope.spawn()`, it will"] # [doc = " execute, even if the spawning task should later panic. `scope()`"] # [doc = " returns once all spawned jobs have completed, and any panics are"] # [doc = " propagated at that point."] pub fn scope < 'scope , OP , R > (op : OP) -> R where OP : FnOnce (& Scope < 'scope >) -> R + Send , R : Send , { in_worker (| owner_thread , _ | { let scope = Scope :: < 'scope > :: new (Some (owner_thread) , None) ; scope . base . complete (Some (owner_thread) , | | op (& scope)) }) }
}

