mkfn!{
    scope_fifo_introspect!();
    # [doc = " Creates a \"fork-join\" scope `s` with FIFO order, and invokes the"] # [doc = " closure with a reference to `s`. This closure can then spawn"] # [doc = " asynchronous tasks into `s`. Those tasks may run asynchronously with"] # [doc = " respect to the closure; they may themselves spawn additional tasks"] # [doc = " into `s`. When the closure returns, it will block until all tasks"] # [doc = " that have been spawned into `s` complete."] # [doc = ""] # [doc = " # Task execution"] # [doc = ""] # [doc = " Tasks in a `scope_fifo()` run similarly to [`scope()`], but there's a"] # [doc = " difference in the order of execution. Consider a similar example:"] # [doc = ""] # [doc = " [`scope()`]: fn.scope.html"] # [doc = ""] # [doc = " ```rust"] # [doc = " # use rustc_thread_pool as rayon;"] # [doc = " // point start"] # [doc = " rayon::scope_fifo(|s| {"] # [doc = "     s.spawn_fifo(|s| { // task s.1"] # [doc = "         s.spawn_fifo(|s| { // task s.1.1"] # [doc = "             rayon::scope_fifo(|t| {"] # [doc = "                 t.spawn_fifo(|_| ()); // task t.1"] # [doc = "                 t.spawn_fifo(|_| ()); // task t.2"] # [doc = "             });"] # [doc = "         });"] # [doc = "     });"] # [doc = "     s.spawn_fifo(|s| { // task s.2"] # [doc = "     });"] # [doc = "     // point mid"] # [doc = " });"] # [doc = " // point end"] # [doc = " ```"] # [doc = ""] # [doc = " The various tasks that are run will execute roughly like so:"] # [doc = ""] # [doc = " ```notrust"] # [doc = " | (start)"] # [doc = " |"] # [doc = " | (FIFO scope `s` created)"] # [doc = " +--------------------+ (task s.1)"] # [doc = " +-------+ (task s.2) |"] # [doc = " |       |            +---+ (task s.1.1)"] # [doc = " |       |            |   |"] # [doc = " |       |            |   | (FIFO scope `t` created)"] # [doc = " |       |            |   +----------------+ (task t.1)"] # [doc = " |       |            |   +---+ (task t.2) |"] # [doc = " | (mid) |            |   |   |            |"] # [doc = " :       |            |   + <-+------------+ (scope `t` ends)"] # [doc = " :       |            |   |"] # [doc = " |<------+------------+---+ (scope `s` ends)"] # [doc = " |"] # [doc = " | (end)"] # [doc = " ```"] # [doc = ""] # [doc = " Under `scope_fifo()`, the spawns are prioritized in a FIFO order on"] # [doc = " the thread from which they were spawned, as opposed to `scope()`'s"] # [doc = " LIFO. So in this example, we can expect `s.1` to execute before"] # [doc = " `s.2`, and `t.1` before `t.2`. Other threads also steal tasks in"] # [doc = " FIFO order, as usual. Overall, this has roughly the same order as"] # [doc = " the now-deprecated [`breadth_first`] option, except the effect is"] # [doc = " isolated to a particular scope. If spawns are intermingled from any"] # [doc = " combination of `scope()` and `scope_fifo()`, or from different"] # [doc = " threads, their order is only specified with respect to spawns in the"] # [doc = " same scope and thread."] # [doc = ""] # [doc = " For more details on this design, see Rayon [RFC #1]."] # [doc = ""] # [doc = " [`breadth_first`]: struct.ThreadPoolBuilder.html#method.breadth_first"] # [doc = " [RFC #1]: https://github.com/rayon-rs/rfcs/blob/master/accepted/rfc0001-scope-scheduling.md"] # [doc = ""] # [doc = " # Panics"] # [doc = ""] # [doc = " If a panic occurs, either in the closure given to `scope_fifo()` or"] # [doc = " in any of the spawned jobs, that panic will be propagated and the"] # [doc = " call to `scope_fifo()` will panic. If multiple panics occurs, it is"] # [doc = " non-deterministic which of their panic values will propagate."] # [doc = " Regardless, once a task is spawned using `scope.spawn_fifo()`, it"] # [doc = " will execute, even if the spawning task should later panic."] # [doc = " `scope_fifo()` returns once all spawned jobs have completed, and any"] # [doc = " panics are propagated at that point."] pub fn scope_fifo < 'scope , OP , R > (op : OP) -> R where OP : FnOnce (& ScopeFifo < 'scope >) -> R + Send , R : Send , { in_worker (| owner_thread , _ | { let scope = ScopeFifo :: < 'scope > :: new (Some (owner_thread) , None) ; scope . base . complete (Some (owner_thread) , | | op (& scope)) }) }
}

